<div class="page-actions"><p>ประวัติบิลและการชำระเงิน</p><a class="button" href="<?= e(route('sales.create')) ?>">+ เปิดบิลขาย</a></div>
<?php require __DIR__.'/../partials/messages.php'; ?>
<section class="card"><form class="filter-form" method="get"><div class="filter-controls"><div><label for="q">เลขบิล</label><input id="q" name="q" value="<?= e($filters['q'] ?? '') ?>"></div><div><label for="from">ตั้งแต่</label><input id="from" name="from" type="date" value="<?= e($filters['from'] ?? '') ?>"></div><div><label for="to">ถึง</label><input id="to" name="to" type="date" value="<?= e($filters['to'] ?? '') ?>"></div><div><label for="status">สถานะ</label><select id="status" name="status"><option value="">ทุกสถานะ</option><?php foreach (['paid' => 'ชำระแล้ว', 'pending' => 'รอชำระ', 'cancelled' => 'ยกเลิก'] as $key => $label): ?><option value="<?= e($key) ?>" <?= ($filters['status'] ?? '') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><button>ค้นหา</button></div></form>
