<?php foreach ($sales as $bill): ?><tr><td><a href="<?= e(route('sales.show', $bill)) ?>"><?= e($bill->bill_no) ?></a><small><?= e($bill->created_at?->format('d/m/Y H:i')) ?></small></td><td><?= e($bill->customer?->name ?: $bill->customer?->phone ?: 'ลูกค้าทั่วไป') ?></td><td><?= e($bill->user?->name) ?></td><td><?= e($bill->total) ?> บาท</td><td><span class="badge <?= $bill->status === 'paid' ? 'good' : 'warning' ?>"><?= e(['paid' => 'ชำระแล้ว', 'pending' => 'รอชำระ', 'cancelled' => 'ยกเลิก'][$bill->status]) ?></span></td></tr><?php endforeach; ?>
<?php if ($sales->isEmpty()): ?><tr><td colspan="5" class="empty-state">ยังไม่มีบิลตามเงื่อนไข <a href="<?= e(route('sales.create')) ?>">เริ่มขาย</a></td></tr><?php endif; ?></tbody></table></div><?php $paginator = $sales; require __DIR__.'/../partials/pagination.php'; ?></section>
